using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Printing;using System.Linq;using System.Reflection;using System.Windows.Forms;using AutosurBuscador;
class TurneroTests {
 static IEnumerable<Control> Walk(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Walk(child))yield return nested;}}
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}
 static void Rows(TurneroPage page,List<Appointment> rows){Set(page,"turns",rows);page.GetType().GetMethod("ShowRows",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(page,null);Application.DoEvents();}
 static List<Appointment> Sample(int count){var rows=new List<Appointment>();for(int i=0;i<count;i++)rows.Add(new Appointment{Fecha="15/10/26",Hora=(8+i/6).ToString("00")+":"+(i%6*10).ToString("00"),Cliente="CLIENTE DE EJEMPLO "+(i+1).ToString("00"),Telefono="Teléfono de ejemplo",Modelo="Renault Kangoo",Patente="DEMO"+i.ToString("00"),Chasis="VIN DE EJEMPLO",Motor="K4M",Servicio="Service de 20.000 km y control general."});return rows;}
 static void Capture(Form form,string file){using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(file);}}
 static bool PrintPage(TurneroPage page,string save){using(var bmp=new Bitmap(827,1169)){bmp.SetResolution(100,100);using(var graphics=Graphics.FromImage(bmp)){graphics.Clear(Color.White);graphics.PageUnit=GraphicsUnit.Pixel;var settings=new PageSettings{PaperSize=new PaperSize("A4",827,1169),Margins=new Margins(30,30,30,30),Landscape=false};var args=new PrintPageEventArgs(graphics,new Rectangle(30,30,767,1109),new Rectangle(0,0,827,1169),settings);page.GetType().GetMethod("PrintPage",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(page,new object[]{null,args});if(save!=null)bmp.Save(save);return args.HasMorePages;}}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 using(var main=new MainForm()){var all=Walk(main).ToArray();var page=all.OfType<TurneroPage>().Single();var tabs=all.OfType<TabControl>().First();tabs.SelectedTab=all.OfType<TabPage>().Single(x=>x.Text=="Turnero");main.Size=new Size(1100,760);main.Show();Application.DoEvents();Rows(page,Sample(60));
 var grid=(DataGridView)Get(page,"grid");var status=(Label)Get(page,"status");status.Text="60 turnos de demostración. Desplazamiento nativo con barras y teclado.\nFecha y hora fijas. Alto de cada turno impreso: 32 mm.";if(grid.ScrollBars!=ScrollBars.Both)throw new Exception("Faltan barras nativas");
 if(!grid.Controls.OfType<HScrollBar>().Any(x=>x.Visible)||!grid.Controls.OfType<VScrollBar>().Any(x=>x.Visible))throw new Exception("Las barras no son visibles con muchas filas y columnas");
 if(grid.RectangleToScreen(grid.ClientRectangle).Top<status.RectangleToScreen(status.ClientRectangle).Bottom)throw new Exception("La grilla queda debajo de los controles");
 grid.CurrentCell=grid.Rows[59].Cells[8];grid.Focus();Application.DoEvents();if(grid.FirstDisplayedScrollingRowIndex<=0||grid.HorizontalScrollingOffset<=0||!grid.Rows[59].Displayed)throw new Exception("No se puede navegar hasta el último turno y Servicio");
 if(!grid.Columns[0].Frozen||!grid.Columns[1].Frozen)throw new Exception("Fecha y hora no permanecen visibles");Console.WriteLine("OK navegación hasta último turno y última columna; barras visibles sin superposición");
 Capture(main,"turnero-pantalla.png");grid.CurrentCell=grid.Rows[0].Cells[0];
 Rows(page,Sample(23));var height=(NumericUpDown)Get(page,"rowHeight");if(height.Value!=32)throw new Exception("La altura inicial no es 32 mm");
 Set(page,"printIndex",0);bool more=PrintPage(page,"turnero-impresion.png");int first=(int)Get(page,"printIndex");if(!more||first<6||first>8)throw new Exception("Las filas no tienen la altura esperada: "+first+" en A4");Console.WriteLine("OK filas altas de 32 mm, "+first+" turnos por primera página A4 vertical");
 int pages=1,count=first;while(more){int before=(int)Get(page,"printIndex");more=PrintPage(page,null);count+=more?(int)Get(page,"printIndex")-before:23-before;if(++pages>10)throw new Exception("Paginación sin avance");}if(count!=23||(int)Get(page,"printIndex")!=0)throw new Exception("Se omitieron turnos o no se reinició la impresión");Console.WriteLine("OK 23 turnos impresos una vez en "+pages+" páginas");
 height.Value=45;Set(page,"printIndex",0);PrintPage(page,null);int taller=(int)Get(page,"printIndex");if(taller<=0||taller>=first)throw new Exception("Cambiar la altura no aumenta las filas");Console.WriteLine("OK altura ajustable de 45 mm: "+taller+" turnos por página");
 height.Value=32;Rows(page,new List<Appointment>());if(Walk(page).OfType<Button>().Where(x=>x.Text=="Vista previa"||x.Text=="Imprimir turnero"||x.Text=="Exportar PDF").Any(x=>x.Enabled))throw new Exception("Permite imprimir sin turnos");Console.WriteLine("OK no imprime una agenda vacía");main.Close();}
 Console.WriteLine("Pruebas del turnero aprobadas.");}
}
